import { Icon } from "@/registry/erbium/ui/icon";
import type { IconProps } from "@/registry/erbium/ui/icon";
import * as React from "react";

import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/registry/erbium/ui/sidebar";

const projects = [
  {
    name: "Design Engineering",
    url: "#",
    icon: "frame",
  },
  {
    name: "Sales & Marketing",
    url: "#",
    icon: "pie-chart",
  },
  {
    name: "Travel",
    url: "#",
    icon: "map",
  },
  {
    name: "Support",
    url: "#",
    icon: "lifebuoy",
  },
  {
    name: "Feedback",
    url: "#",
    icon: "send",
  },
] satisfies ({ icon: IconProps["name"] } & Record<string, unknown>)[];

function ControlledSidebarTrigger() {
  const { isMobile, open, openMobile } = useSidebar();
  const isOpen = isMobile ? openMobile : open;

  return (
    <SidebarTrigger size="sm">
      <span>{isOpen ? "Close" : "Open"} Sidebar</span>
    </SidebarTrigger>
  );
}

export default function AppSidebar() {
  const [open, setOpen] = React.useState(true);

  return (
    <SidebarProvider open={open} onOpenChange={setOpen}>
      <Sidebar>
        <SidebarContent>
          <SidebarGroup>
            <SidebarGroupLabel>Projects</SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu>
                {projects.map((project) => (
                  <SidebarMenuItem key={project.name}>
                    <SidebarMenuButton render={<a href={project.url} />}>
                      <Icon name={project.icon} />
                      <span>{project.name}</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                ))}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
      </Sidebar>
      <SidebarInset>
        <header className="flex h-12 items-center justify-between px-4">
          <ControlledSidebarTrigger />
        </header>
      </SidebarInset>
    </SidebarProvider>
  );
}

import AppSidebar from "../examples/sidebar-controlled";

const Example = () => <AppSidebar />;

export default Example;
